CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'Active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS departments (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, code VARCHAR(10) NOT NULL UNIQUE, consultation_fee DECIMAL(10,2) NOT NULL DEFAULT 500, status VARCHAR(20) NOT NULL DEFAULT 'Active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS doctors (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT, name VARCHAR(100) NOT NULL, qualification VARCHAR(100), department_id INT, experience VARCHAR(50), consultation_fee DECIMAL(10,2) NOT NULL DEFAULT 500, status VARCHAR(20) NOT NULL DEFAULT 'Available', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_doctors_user FOREIGN KEY (user_id) REFERENCES users(id), CONSTRAINT fk_doctors_department FOREIGN KEY (department_id) REFERENCES departments(id));
CREATE TABLE IF NOT EXISTS patients (id INT AUTO_INCREMENT PRIMARY KEY, patient_id VARCHAR(20) NOT NULL UNIQUE, user_id INT UNIQUE, full_name VARCHAR(100) NOT NULL, guardian_name VARCHAR(100), dob DATE, gender VARCHAR(20), mobile VARCHAR(15) NOT NULL, email VARCHAR(150), address VARCHAR(255), city VARCHAR(100), state VARCHAR(100), pin_code VARCHAR(10), emergency_contact VARCHAR(15), blood_group VARCHAR(10), status VARCHAR(20) NOT NULL DEFAULT 'Active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_patients_user FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS appointments (id INT AUTO_INCREMENT PRIMARY KEY, appointment_id VARCHAR(20) NOT NULL UNIQUE, patient_id INT NOT NULL, doctor_id INT NOT NULL, department_id INT NOT NULL, appointment_date DATE NOT NULL, appointment_time VARCHAR(10) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'Scheduled', priority TINYINT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_appointment_slot UNIQUE (doctor_id, appointment_date, appointment_time), CONSTRAINT fk_appointments_patient FOREIGN KEY (patient_id) REFERENCES patients(id), CONSTRAINT fk_appointments_doctor FOREIGN KEY (doctor_id) REFERENCES doctors(id), CONSTRAINT fk_appointments_department FOREIGN KEY (department_id) REFERENCES departments(id));
CREATE TABLE IF NOT EXISTS tokens (id INT AUTO_INCREMENT PRIMARY KEY, token_number VARCHAR(20) NOT NULL UNIQUE, appointment_id INT NOT NULL UNIQUE, department_id INT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'Waiting', called_at TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_tokens_appointment FOREIGN KEY (appointment_id) REFERENCES appointments(id), CONSTRAINT fk_tokens_department FOREIGN KEY (department_id) REFERENCES departments(id));
CREATE TABLE IF NOT EXISTS consultations (id INT AUTO_INCREMENT PRIMARY KEY, appointment_id INT NOT NULL UNIQUE, patient_id INT NOT NULL, doctor_id INT NOT NULL, symptoms TEXT, diagnosis TEXT, doctor_notes TEXT, follow_up_date DATE, status VARCHAR(20) NOT NULL DEFAULT 'In Progress', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_consultations_appointment FOREIGN KEY (appointment_id) REFERENCES appointments(id), CONSTRAINT fk_consultations_patient FOREIGN KEY (patient_id) REFERENCES patients(id), CONSTRAINT fk_consultations_doctor FOREIGN KEY (doctor_id) REFERENCES doctors(id));
CREATE TABLE IF NOT EXISTS prescriptions (id INT AUTO_INCREMENT PRIMARY KEY, consultation_id INT NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_prescriptions_consultation FOREIGN KEY (consultation_id) REFERENCES consultations(id));
CREATE TABLE IF NOT EXISTS prescription_items (id INT AUTO_INCREMENT PRIMARY KEY, prescription_id INT NOT NULL, medicine_name VARCHAR(150) NOT NULL, dosage VARCHAR(50), frequency VARCHAR(50), duration VARCHAR(50), instructions VARCHAR(255), CONSTRAINT fk_prescription_items_prescription FOREIGN KEY (prescription_id) REFERENCES prescriptions(id));
CREATE TABLE IF NOT EXISTS notifications (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, message VARCHAR(255) NOT NULL, is_read TINYINT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_notifications_user FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS payments (id INT AUTO_INCREMENT PRIMARY KEY, appointment_id INT NOT NULL, amount DECIMAL(10,2) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'Pending', payment_method VARCHAR(30), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_payments_appointment FOREIGN KEY (appointment_id) REFERENCES appointments(id));
CREATE TABLE IF NOT EXISTS audit_logs (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT, action VARCHAR(150) NOT NULL, description VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_audit_logs_user FOREIGN KEY (user_id) REFERENCES users(id));
CREATE INDEX IF NOT EXISTS idx_appointments_date ON appointments (appointment_date);
CREATE INDEX IF NOT EXISTS idx_tokens_queue ON tokens (department_id, status, created_at);
CREATE INDEX IF NOT EXISTS idx_patients_mobile ON patients (mobile);
